#!/bin/bash
# Control for m3-a1c-dev60-dn: same 38 tasks, same roles (ledger, checker) on Sonnet instead of Mercury, Haiku acting.
cd /home/user/workflow-foundry
W=/var/tmp/foundry-work
while pgrep -f ab-chain4.sh >/dev/null; do sleep 60; done
log() { echo "$* $(date -u +%FT%TZ)" >> $W/launches.log; }
free=$(df --output=avail -k / | tail -1); [ "$free" -lt 1048576 ] && { log "a1csp-dev60-38 NOT STARTED: <1GB free"; exit 9; }
node experiments/autobench/run.mjs --model claude-haiku-5-5 --harness codeowned --node-models ledger=claude-sonnet-5-5,checker=claude-sonnet-5-5 --tasks sales.chatgpt_lead_summary_generator,sales.qualify_lead,sales.docusign_sequential_signing,sales.soft_matching,sales.advance_opportunity_stage,sales.vendor_review_prep,sales.competitive_displacement_outreach,sales.zoom_meeting_followup,sales.partnership_contract,sales.chatgpt_proposal_customization,marketing.win_loss_analysis,marketing.linkedin_company_update,marketing.customer_story_intake,marketing.customer_feedback_aggregation,marketing.engagement_optimization,marketing.social_contest,marketing.community_engagement,marketing.featured_snippet,marketing.social_content_calendar,marketing.customer_milestone,operations.parking_allocation_management,operations.zoom_dr_drill,operations.cross_training_assignment,operations.docusign_contractor_offboard,operations.loading_dock_scheduling,operations.zoom_training_setup,operations.overtime_threshold_monitoring,operations.calendar_airtable_maintenance,operations.invoice_shipping_trigger,operations.asana_safety_walk_log,support.intercom_reactivation_campaign,support.intercom_zoho_customer_360,support.intercom_demo_scheduling,support.intercom_sentiment_escalation,support.gorgias_quality_audit,support.reamaze_cross_platform_dedup,support.intercom_multi_product_routing,support.helpcrunch_zoho_desk_bridge --date-note --budget 0.75 --cap 8 --concurrency 2 --run-id a1csp-dev60-38 >> $W/a1csp-dev60-38.log 2>&1; log "a1csp-dev60-38 exit $? (CLI $(claude --version | cut -d' ' -f1))"
